using System;using System.Linq;
namespace IdleIntelligence.Core
{
 public static class MetaRules
 {
  public static int Level(GameState s,string id){int i=Array.FindIndex(MetaBalance.Axioms,n=>n.Id==id);return i<0?0:Math.Max(s.Meta.axioms[i],(id=="C02"&&s.Challenges.Progress.unlocks.Contains("analysis-planner")||id=="C03"&&s.Challenges.Progress.unlocks.Contains("crafting-planner"))?1:0);}
  public static double Pow(GameState s,string id)=>Math.Pow(PrestigeRules.EFor(s,id),Level(s,id));
  public static bool Secondary(GameState s,string id)=>s.Workshop.activeModel==id&&Level(s,"D06")>0;
  public static double Factor(GameState s,string kind){var model=MetaBalance.Models.FirstOrDefault(m=>m.Id==s.Workshop.activeModel);return model!=null&&model.Kind==kind?1+(model.Base-1)*(1+PrestigeRules.V("modelPrimaryLevel")*s.Workshop.activeModelLevel):1;}
  public static double Core(GameState s){if(string.IsNullOrEmpty(s.Workshop.activeModel))return 1;double coupling=Level(s,"D05")>0?Math.Min(PrestigeRules.V("modelCouplingCap"),1+PrestigeRules.V("modelCouplingScale")*(Math.Pow(PrestigeV3.IntegrationBase(s),s.Workshop.integration)-1)):1;return 1+(PrestigeRules.V("modelCore")*(1+PrestigeRules.V("modelCoreLevel")*s.Workshop.activeModelLevel)-1)*Math.Pow(ItemSystemV3.Enabled(s)?ItemV3Balance.Get("prestige.axioms.A06"):PrestigeRules.V("modelAxiomCore"),Level(s,"A06"))*Math.Pow(ItemSystemV3.Enabled(s)?ItemV3Balance.Get("prestige.axioms.D03"):PrestigeRules.V("modelDevelopmentCore"),Level(s,"D03"))*coupling*(1+Workshop.Device(s,"modelEcho"));}
  public static int IntegrationLimit(GameState s)=>(int)((ItemSystemV3.Enabled(s)?ItemV3Balance.Get("prestige.training.integrationLimit"):PrestigeRules.V("integrationLimit"))+PrestigeRules.V("trainingSoftScale")*Level(s,"A05"));
  public static ScientificNumber AxiomCost(GameState s,string id){var node=MetaBalance.Axioms.FirstOrDefault(n=>n.Id==id);if(node==null)return null;int l=Level(s,id);return l<node.Costs.Length?ScientificNumber.From(node.Costs[l]):id=="A02"?ScientificNumber.From(PrestigeRules.V("axiomTailPrice")).Multiply(ScientificNumber.From(PrestigeRules.V("axiomTailGrowth")).Pow(l-PrestigeRules.V("axiomCreditBoundedLevels"))):null;}
  public static GameState Buy(GameState state,string id){if(ChallengeRules.Active(state)||ItemSystemV3.Enabled(state)&&!state.ItemSystemV3.axiomDiscovered)return state;var cost=AxiomCost(state,id);if(cost==null||ScientificNumber.FromData(state.Meta.available).CompareTo(cost)<0)return state;var s=state.Copy();s.Meta.available=ScientificNumber.FromData(s.Meta.available).Subtract(cost).ToData();s.Meta.axioms[Array.FindIndex(MetaBalance.Axioms,n=>n.Id==id)]++;s.Prestige.revision++;s.Workshop.revision++;LocalJournal.Record(s,"axiom-upgrade-buy",permanent:false);return s;}
  public static ScientificNumber Threshold(GameState s)=>ScientificNumber.FromData(s.Meta.total).Add(ScientificNumber.One).Times(PrestigeRules.V("axiomThreshold"));
  public static ScientificNumber Reward(GameState s)=>ItemSystemV3.Enabled(s)&&!s.ItemSystemV3.axiomDiscovered?ScientificNumber.Zero:ChallengeRules.Active(s)?ScientificNumber.Zero:s.Meta.resets==0&&s.Prestige.known.Distinct().Count()<PrestigeRules.V("firstAxiomNodes")?ScientificNumber.Zero:s.Prestige.Cycle.Add(PrestigeRules.Claim(s)).Divide(Threshold(s)).Pow(.5).Times(1+Workshop.Device(s,"axiomResonance")).Multiply(ItemSystemV3.AxiomFactor(s)).Floor();
  public static ScientificNumber CreditFactor(GameState s)=>ScientificNumber.FromData(s.Meta.total).Add(ScientificNumber.One).Pow(PrestigeRules.V("axiomCreditExponent")+PrestigeRules.V("axiomCreditLevelExponent")*Math.Min(PrestigeRules.V("axiomCreditBoundedLevels"),Level(s,"A02"))).Multiply(ScientificNumber.From(PrestigeRules.V("axiomCreditTail")).Pow(Math.Max(0,Level(s,"A02")-PrestigeRules.V("axiomCreditBoundedLevels"))));
  public static string[] RetainedNodes(GameState s)=>s.Workshop.nodes.Where(id=>new[]{"W01","W02","W06"}.Contains(id)||Level(s,"B01")>0&&new[]{"H01","H02","H03","H04","H05"}.Contains(id)||Level(s,"B02")>0&&new[]{"T03","T06","F02","F03","F05","I06","I07"}.Contains(id)).ToArray();
  public static string ResetPreview(GameState s)=>"Erhalten: Profil, Namen, Gems, AP, dauerhafte Statistik und abgeholte Belohnungen, Modelle samt Leveln und Auswahl, Erkenntnis, Forschung und laufende Forschung/Analyse/Modulherstellung, Inventar, Ausrüstung, Materialien, Baupläne, permanente Slots, Axiome, bekannte Knoten und Einstellungen.\n\nAktive INT-Knoten bleiben: "+(RetainedNodes(s).Length==0?"keine":string.Join(", ",RetainedNodes(s)))+".\n\nEntfällt: aktuelles INT-Guthaben/ausgegebene und Zyklus-INT, Anspruch/Einkommensledger, übrige aktive INT-Knoten, Hardware, Daten, alle drei Trainingslevel und aktives Training, wartende Queues, Combo/Overdrive. Credits starten bei 50; ein enthaltener Grundagent kauft ggf. einen Rechner bezahlt. Gesamt-INT und bester INT-Stand bleiben erhalten. Wartende bezahlte Module werden zuerst erstattet. Trainingsrekorde werden für B05 gesichert.";
  public static GameState AxiomReset(GameState state,long ticket=-1)
  {
   if(ChallengeRules.Active(state)||ticket>=0&&ticket!=state.Prestige.revision)return state;var reward=Reward(state);if(reward.CompareTo(ScientificNumber.One)<0)return state;var s=state.Copy();var p=s.Prestige;var gain=PrestigeRules.Claim(s);p.Cycle=p.Cycle.Add(gain);p.Total=p.Total.Add(gain);PrestigeRules.Discover(s);s=Workshop.Discover(s);p=s.Prestige;foreach(var f in s.Industry.foundries)f.queue=Array.Empty<string>();
   foreach(var j in p.moduleQueue){var d=ItemBalance.Modules.First(m=>m.Id==j.id);for(int c=0;c<d.Costs.Length;c++)s.Workshop.components[c]+=(long)d.Costs[c];}
   p.moduleQueue=Array.Empty<Job>();p.trainingQueue=Array.Empty<TrainingTarget>();p.researchQueue=Array.Empty<string>();s.Workshop.nodes=RetainedNodes(s);s.Meta.available=ScientificNumber.FromData(s.Meta.available).Add(reward).ToData();s.Meta.total=ScientificNumber.FromData(s.Meta.total).Add(reward).ToData();s.Meta.resets++;s.Legacy.cycle=Array.Empty<LegacyFactor>();s.Legacy.classUpgrades=Array.Empty<string>();s.Legacy.classUpgradesRecorded=true;s.Meta.records=(int[])s.Meta.cycleRecords.Clone();s.Meta.cycleRecords=new int[3];s.Meta.cycleStartedAt=s.SavedAt;if(s.Meta.tutorial!="lab")s.Meta.tutorial="axiom";
   p.Cycle=p.Free=p.Spent=p.Eligible=p.Entitlement=ScientificNumber.Zero;p.lastGain=ScientificNumber.Zero.ToData();p.autoSeconds=p.otherAutoSeconds=0;ResetControls.ClearIntent(s);s.Meta.intentAxiom=false;p.intentResearch=Array.Empty<string>();p.intentAnalysis=p.intentCrafting=p.intentTraining=false;
   s.RunCredits=ScientificNumber.Zero;s.RunCreditsRecorded=true;s.Lifetime.runMilestoneClasses=Array.Empty<string>();s.Credits=ScientificNumber.From(Balance.StartCredits);s.Data=ScientificNumber.Zero;s.Hardware=new long[s.Hardware.Length];s.ModelLevel=0;s.Quality=s.Efficiency=s.Workshop.integration=0;s.Training=null;s.Combo=s.Charge=0;s.LastTap=-1;s.ActiveUntil=s.CooldownUntil=0;s.Industry.trainingStarted=0;s.Workshop.runStartedAt=s.SavedAt;s.Workshop.qualityCompletions=s.Workshop.efficiencyCompletions=0;s.Workshop.lastTrack="";p.milestones=Array.Empty<string>();p.revision++;s.Workshop.revision++;if(PrestigeRules.Has(s,"I06"))s=Game.Buy(s,"calculator");ItemSystemV3.ResetProduction(s,true);LocalBalanceHistory.Close(state,s,"axiom",gain,reward);LocalJournal.Record(s,"axiom-reset",permanent:false);return s;
  }
  public static ScientificNumber ModelCost(GameState s)=>Game.Ceil(ScientificNumber.From(PrestigeRules.V("modelPriceBase")).Multiply(ScientificNumber.From(PrestigeRules.V("modelPriceGrowth")).Pow(s.Meta.models.Count(l=>l>=0))));
  public static ScientificNumber UpgradeCost(GameState s,int index)=>Game.Ceil(ScientificNumber.From(PrestigeRules.V("modelUpgradeBase")).Multiply(ScientificNumber.From(PrestigeRules.V("modelUpgradeGrowth")).Pow(Math.Max(0,s.Meta.models[index]))).Times(Math.Pow(ItemSystemV3.Enabled(s)?ItemV3Balance.Get("prestige.axioms.D02"):PrestigeRules.V("modelDiscount"),Level(s,"D02"))));
  public static int ModelLimit(GameState s)=>(int)(PrestigeRules.V("modelBaseLimit")+PrestigeRules.V("modelLimitStep")*Level(s,"D03"));
  public static GameState Develop(GameState state)
  {var pool=Enumerable.Range(0,10).Where(i=>state.Meta.models[i]<0).ToArray();var price=ModelCost(state);if(ChallengeRules.Active(state)||!state.Prestige.lab||pool.Length==0||ScientificNumber.FromData(state.Prestige.knowledge).CompareTo(price)<0)return state;var s=state.Copy();s.Meta.rng=unchecked(s.Meta.rng*1664525u+1013904223u);int n=pool[(int)Math.Floor(s.Meta.rng/4294967296d*pool.Length)];s.Meta.models[n]=0;s.Prestige.knowledge=ScientificNumber.FromData(s.Prestige.knowledge).Subtract(price).ToData();if(string.IsNullOrEmpty(s.Workshop.activeModel)){s.Workshop.activeModel=MetaBalance.Models[n].Id;s.Workshop.activeModelLevel=0;}s.Workshop.revision++;LocalJournal.Record(s,"ki-develop",permanent:false);return s;}
  public static GameState Upgrade(GameState state,string id){int n=Array.FindIndex(MetaBalance.Models,m=>m.Id==id);if(ChallengeRules.Active(state)||n<0||state.Meta.models[n]<0||state.Meta.models[n]>=ModelLimit(state))return state;var price=UpgradeCost(state,n);if(ScientificNumber.FromData(state.Prestige.knowledge).CompareTo(price)<0)return state;var s=state.Copy();s.Meta.models[n]++;s.Prestige.knowledge=ScientificNumber.FromData(s.Prestige.knowledge).Subtract(price).ToData();if(s.Workshop.activeModel==id)s.Workshop.activeModelLevel=s.Meta.models[n];s.Workshop.revision++;LocalJournal.Record(s,"ki-upgrade",permanent:false);return s;}
  public static GameState Select(GameState state,string id){int n=Array.FindIndex(MetaBalance.Models,m=>m.Id==id);if(ChallengeRules.Active(state)||state.Workshop.activeModel==(id??"")||!string.IsNullOrEmpty(id)&&(n<0||state.Meta.models[n]<0))return state;var s=state.Copy();s.Workshop.activeModel=id??"";s.Workshop.activeModelLevel=n<0?0:s.Meta.models[n];var slots=Workshop.ActiveSlots(s);for(int i=0;i<slots.Length;i++)if(!slots[i])s.Workshop.equipped[i]="";s.Workshop.revision++;LocalJournal.Record(s,"ki-select",permanent:false);return s;}
  public static GameState Phase(GameState s,int phase)=>Level(s,"D04")>0&&!string.IsNullOrEmpty(s.Meta.modelPlan[phase])?Select(s,s.Meta.modelPlan[phase]):s;
  public static void Validate(GameState s){var m=s.Meta;if(!string.IsNullOrEmpty(s.Workshop.activeModel)&&!MetaBalance.Models.Any(d=>d.Id==s.Workshop.activeModel)||s.Workshop.activeModelLevel<0||s.Workshop.activeModelLevel>PrestigeRules.V("modelLevelLimit"))throw new FormatException("Invalid active model");if(m==null||m.schema!=1||m.axioms==null||m.axioms.Length!=24||m.models==null||m.models.Length!=10||m.models.Any(l=>l< -1||l>PrestigeRules.V("modelLevelLimit"))||m.axioms.Where((l,i)=>l<0||i!=1&&l>MetaBalance.Axioms[i].Costs.Length).Any()||m.resets<0||!ScientificNumber.Finite(m.cycleStartedAt)||m.cycleStartedAt<0||m.modelPlan==null||m.modelPlan.Length!=3||m.modelPlan.Any(id=>!string.IsNullOrEmpty(id)&&!MetaBalance.Models.Any(d=>d.Id==id))||m.records==null||m.records.Length!=3||m.records.Any(n=>n<0)||m.cycleRecords==null||m.cycleRecords.Length!=3||m.cycleRecords.Any(n=>n<0)||m.rebuild==null||m.rebuild.Any(id=>!PrestigeBalance.Nodes.Any(n=>n.Id==id))||m.rebuild.Distinct().Count()!=m.rebuild.Length||m.analysisRecipe<0||m.analysisRecipe>=6||!new[]{1,5,10}.Contains(m.craftTarget)||Workshop.Index(m.craftRecipe)<0||m.fusionTarget<0||m.fusionTarget>5||m.fusionTypes==null||m.fusionTypes.Any(id=>Workshop.Index(id)<0)||m.tutorial!=""&&m.tutorial!="lab"&&m.tutorial!="axiom")throw new FormatException("Invalid axioms/models");foreach(var n in new[]{m.available,m.total,m.intReserve,m.axiomMinimum})ScientificNumber.FromData(n);if(ScientificNumber.FromData(m.axiomMinimum).CompareTo(ScientificNumber.One)<0||ScientificNumber.FromData(m.available).CompareTo(ScientificNumber.FromData(m.total))>0)throw new FormatException("Invalid axiom ledger");foreach(var a in new[]{m.passiveRemainders,m.salvageRemainders})if(a==null||a.Length!=ItemBalance.ComponentIds.Length||a.Any(n=>!ScientificNumber.Finite(n)||n<0||n>=1))throw new FormatException("Invalid meta remainders");if(!ScientificNumber.Finite(m.analysisSeconds)||!ScientificNumber.Finite(m.craftSeconds)||m.analysisSeconds<0||m.craftSeconds<0)throw new FormatException("Invalid planner clock");}
 }
}
